import sys; sys.path.insert(0,'/tmp')
from mt64 import MT64
N=60
def model(seed,n,draw_all=True):
    m=MT64(seed)
    buf=[None]*n
    for i in range(N):
        if draw_all:
            r=m.real2(); k=int(r*(i+1))
            if i<n: buf[i]=i
            elif k<n: buf[k]=i
        else:
            if i<n: buf[i]=i
            else:
                r=m.real2(); k=int(r*(i+1))
                if k<n: buf[k]=i
    return buf
